import math

def calculate_inradius(n):
    # Side lengths are n, n+1, n+2
    # Semi-perimeter s = (3n + 3) / 2
    # Inradius r = (1/6) * sqrt(3 * (n^2 - 1))

    # Check for valid triangle (n>1 is required for n-1 > 0, but we start at n=2)
    if n <= 1:
        return None

    r = (1 / 6) * math.sqrt(3 * (n**2 - 1))
    return r

results = {}
for n in range(2, 11):
    r = calculate_inradius(n)
    results[n] = r

print("N | R")
print("-" * 15)
for n, r in results.items():
    print(f"{n} | {r}")

# Check proximity to 1
close_to_one = []
TOLERANCE = 0.1 # Arbitrary tolerance for "close"

for n, r in results.items():
    if abs(r - 1) < TOLERANCE:
        close_to_one.append((n, r))

print("\nValues close to 1 (Tolerance =", TOLERANCE, "):")
if close_to_one:
    for n, r in close_to_one:
        print(f"N={n}, R={r}")
else:
    print("None found within tolerance.")
